package com.hms.website;
import com.hms.tenancy.*; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/public/hospitals/{tenantSlug}/content") public class PublicContentDetailController {private final TenantRepository tenants;private final WebsiteContentRepository content;public PublicContentDetailController(TenantRepository t,WebsiteContentRepository c){tenants=t;content=c;} @GetMapping("/{slug}") public WebsiteContentItem get(@PathVariable String tenantSlug,@PathVariable String slug){UUID tenant=tenants.findBySlug(tenantSlug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(tenantSlug));return content.findByTenantIdAndSlugAndStatus(tenant,slug,ContentStatus.PUBLISHED).orElseThrow(()->new IllegalArgumentException("Published content not found"));}}
